from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The separator is the solid middle row/column; compare corresponding panels.
    for c in range(w):
        if 2*c + 1 == w and all(row[c] == grid[0][c] for row in grid):
            a = [row[:c] for row in grid]
            b = [row[c+1:] for row in grid]
            break
    else:
        for r in range(h):
            if 2*r + 1 == h and len(set(grid[r])) == 1:
                a, b = grid[:r], grid[r+1:]
                break
        else:
            raise ValueError('No centered solid separator')
    bg_a = Counter(x for row in a for x in row).most_common(1)[0][0]
    bg_b = Counter(x for row in b for x in row).most_common(1)[0][0]
    return [[3 if a[i][j] != bg_a and b[i][j] == bg_b else 4
             for j in range(len(a[0]))] for i in range(len(a))]
